import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`blog-audit`,heroTitle:`Get more blog traffic in minutes`,heroSubtitle:`Perplexity Computer audits every post, rewrites your meta tags, and builds a 30-day content calendar — automatically.`,heroCta:`Get Started`,inputUrlCta:`Audit my blog`,inputUrlPlaceholder:`yourblog.com`,inputUrlPrefill:`Go to {url} and run a full SEO audit of this blog. (1) Audit every published post for on-page SEO — meta titles, meta descriptions, header structure, internal linking, image alt text, and URL slugs. (2) Rewrite underperforming meta titles and descriptions to maximize click-through rates from Google search results. (3) Identify the 10 highest-traffic-potential topics based on keyword gaps and trending searches in your niche. (4) Build a 30-day content calendar with post titles, target keywords, and outlines for each topic. (5) Write Pinterest pin descriptions optimized for Pinterest search for every existing and planned post. (6) Deliver a complete blog optimization report with rewritten meta tags, content calendar, and Pinterest strategy.`,heroOverlaySteps:[`Auditing every post for meta tags, headers, internal links, and alt text`,`Rewriting meta titles and descriptions for higher Google click-through rates`,`Identifying the 10 highest-traffic-potential topics in your niche`,`Content calendar, rewritten meta tags, and Pinterest pin descriptions — ready to publish`],generatingSteps:[`Visiting {url} to audit every post’s on-page SEO and site structure`,`Designing an agent to rewrite meta titles and descriptions for maximum CTR`,`Configuring keyword gap analysis and 30-day content calendar pipelines`,`Setting up Pinterest pin descriptions and blog optimization report`],featureSectionTitle:`From blog to traffic`,featureCardTitles:[`Connects to your blogging stack`,`Posts ready to rank`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Google Search Console, Google Analytics, Canva, Notion — Computer plugs into your tools so audits, content plans, and pin designs happen in one workflow.`,`Rewritten meta titles. Optimized descriptions. Pinterest pin copy. 30-day content calendar. Computer delivers SEO fixes you can apply to your blog today.`],capabilitySectionTitle:`Your blog growth team, on autopilot`,capabilitySectionSubtitle:`Paste your blog URL, get back an SEO audit and content plan.`,capabilityCards:[{title:`Post-by-Post SEO Audit`,description:`Computer can audit every published post — meta titles, descriptions, header hierarchy, image alt text, and internal links — and flag what’s costing you traffic.`},{title:`Meta Tag Rewrites`,description:`Computer can rewrite meta titles and descriptions across your entire blog to maximize click-through rates from Google search results.`},{title:`Content Calendar`,description:`Computer can identify the highest-traffic-potential topics in your niche and build a 30-day calendar with post titles, target keywords, and outlines.`},{title:`Connect Your Tools`,description:`Computer can read from Google Search Console, Google Analytics, Canva, and Notion — build workflows across your blog and social channels.`},{title:`Knows Your Blog`,description:`Computer can remember your niche, writing style, top-performing posts, and keyword targets across sessions — so every audit builds on what came before.`},{title:`Rank & Traffic Alerts`,description:`Computer can watch your post rankings and traffic weekly — and alert you when a post drops or a new keyword opportunity appears.`}]});export{t as default};
